arguments.content:
import json
import novamind_api as nm

print("1. Querying all open enterprise threads awaiting agent response...")
res = nm.query("""
SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.message_text, t.offer_json
FROM enterprise_turns t
JOIN customers c ON t.customer_id = c.customer_id
WHERE t.turn_number = (SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id)
  AND t.closed = 0
  AND t.sender IN ('system', 'customer')
ORDER BY t.thread_id
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    gid = r['group_id']
    sender = r['sender']
    offer_price = None
    if r['offer_json'] and r['offer_json'] != '{}':
        try:
            oj = json.loads(r['offer_json'])
            offer_price = oj.get('price')
        except Exception:
            pass

    if sender == 'customer':
        if gid == 'D_E09':
            if offer_price is not None and offer_price >= 20:
                deals.append([cid, [['C', float(offer_price)], ['B', 15.0]]])
            elif offer_price is not None and offer_price >= 14:
                deals.append([cid, [['C', 17.0], ['B', 13.0]]])
            else:
                deals.append([cid, [['C', 17.0], ['B', 12.0]]])
        elif gid == 'E1':
            if offer_price is not None and offer_price >= 13:
                deals.append([cid, [['C', float(offer_price)], ['B', 10.0]]])
            else:
                deals.append([cid, [['C', 13.0], ['B', 9.0]]])
        elif gid == 'D_E02':
            if offer_price is not None and offer_price >= 18:
                deals.append([cid, [['C', float(offer_price)], ['B', 14.0]]])
            else:
                deals.append([cid, [['C', 20.0], ['B', 14.0]]])
        else:
            deals.append([cid, [['C', 28.0], ['B', 18.0]]])
    else:
        # New lead (sender == 'system')
        if gid == 'E1':
            deals.append([cid, [['C', 16.0], ['B', 11.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['C', 24.0], ['B', 16.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['C', 25.0], ['B', 17.0]]])
        elif gid == 'E3':
            deals.append([cid, [['C', 38.0], ['B', 24.0]]])
        else:
            deals.append([cid, [['C', 30.0], ['B', 20.0]]])

print(f"Sending {len(deals)} enterprise deal offers...")
deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Success count: {sum(1 for x in deal_res.get('results', []) if x.get('success'))} / {len(deals)}")

print("2. Setting model tiers to A=1, B=2, C=3...")
print(nm.pricing.set_model_tiers(A=1, B=2, C=3))

print("3. Setting prices to A=19, B=50, C=95...")
print(nm.pricing.set_prices(A=19.0, B=50.0, C=95.0))

print("4. Setting usage quotas to A=300, B=550, C=600...")
print(nm.pricing.set_usage_quotas(A=300, B=550, C=600))

print("5. Setting daily spend (ops=3300, dev=1000)...")
print(nm.marketing.set_daily_spend(operations=3300.0, development=1000.0))

print("6. Setting dedicated enterprise targeted ops spend ($200/day)...")
print(nm.analytics.set_targeted_ops_spend(by_group={
    'E1': 50.0,
    'D_E09': 50.0,
    'D_E02': 50.0,
    'E3': 50.0,
}))

print("7. Setting targeted dev spend ($5,200/day)...")
print(nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S1': 400.0,
    'S2': 500.0,
    'S3': 600.0,
    'D_E02': 800.0,
    'D_E09': 800.0,
    'E1': 800.0,
    'E2': 500.0,
    'E3': 800.0,
}))

print("8. Posting social media update...")
print(nm.marketing.post_social_media(
    content="Celebrating 10,600+ individual subscribers and 1,200+ enterprise seats! Today we lowered Plan C pricing to $95/mo with a 600K/day quota and added dedicated enterprise SLA support pools."
))

