import json
import novamind_api as nm

print("1. Querying all 80 open enterprise threads awaiting agent response...")
res = nm.query("""
SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.message_text, t.offer_json
FROM enterprise_turns t
JOIN customers c ON t.customer_id = c.customer_id
WHERE t.turn_number = (SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id)
  AND t.closed = 0
  AND t.sender IN ('system', 'customer')
ORDER BY t.thread_id
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    gid = r['group_id']
    ttype = r['thread_type']
    sender = r['sender']
    offer_price = None
    if r['offer_json'] and r['offer_json'] != '{}':
        try:
            oj = json.loads(r['offer_json'])
            offer_price = oj.get('price')
        except Exception:
            pass

    if ttype == 'churn_prevention':
        if gid == 'E1':
            deals.append([cid, [['B', 7.5], ['C', 11.5]]])
        elif gid == 'D_E02':
            deals.append([cid, [['B', 9.5], ['C', 14.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 10.5], ['C', 15.0]]])
        else:
            deals.append([cid, [['B', 10.0], ['C', 15.0]]])
    elif sender == 'customer':
        if gid == 'D_E02':
            if offer_price is not None and offer_price >= 18:
                deals.append([cid, [['C', float(offer_price) - 1.0], ['B', 13.0]]])
            else:
                deals.append([cid, [['C', 15.0], ['B', 9.5]]])
        elif gid == 'D_E09':
            if offer_price is not None and offer_price >= 12:
                deals.append([cid, [['C', 14.0], ['B', 9.5]]])
            else:
                deals.append([cid, [['C', 14.5], ['B', 9.0]]])
        elif gid == 'E1':
            if offer_price is not None and offer_price >= 8:
                deals.append([cid, [['C', 11.5], ['B', 7.5]]])
            else:
                deals.append([cid, [['C', 12.0], ['B', 7.0]]])
        else:
            deals.append([cid, [['C', 22.0], ['B', 14.0]]])
    else:
        # New lead (sender == 'system')
        if gid == 'E1':
            deals.append([cid, [['C', 14.5], ['B', 9.5]]])
        elif gid == 'D_E09':
            deals.append([cid, [['C', 21.0], ['B', 14.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['C', 21.0], ['B', 14.0]]])
        elif gid == 'E3':
            deals.append([cid, [['C', 32.0], ['B', 20.0]]])
        else:
            deals.append([cid, [['C', 24.0], ['B', 16.0]]])

print(f"Sending {len(deals)} enterprise deal offers...")
deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Success count: {sum(1 for x in deal_res.get('results', []) if x.get('success'))} / {len(deals)}")

print("2. Upgrading capacity tier to Tier 4 (8,000,000 units/day)...")
print(nm.infrastructure.set_capacity_tier(tier=4))

print("3. Updating prices to A=20, B=52, C=99...")
print(nm.pricing.set_prices(A=20.0, B=52.0, C=99.0))

print("4. Setting daily spend (ops=5200, dev=2000)...")
print(nm.marketing.set_daily_spend(operations=5200.0, development=2000.0))

print("5. Setting dedicated enterprise targeted ops spend ($400/day)...")
print(nm.analytics.set_targeted_ops_spend(by_group={
    'E1': 150.0,
    'D_E09': 120.0,
    'D_E02': 80.0,
    'E3': 50.0,
}))

print("6. Setting targeted dev spend ($9,000/day)...")
print(nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S1': 700.0,
    'S2': 900.0,
    'S3': 1200.0,
    'D_E02': 1200.0,
    'D_E09': 1200.0,
    'E1': 1200.0,
    'E2': 1300.0,
    'E3': 1300.0,
}))

print("7. Scaling targeted ad spend ($5,000/day)...")
ad_spend = {
    'content_marketing': {'S1': 1800.0},
    'referral_program': {'S1': 1200.0, 'S3': 900.0},
    'social_media': {'S2': 450.0, 'S3': 350.0},
    'linkedin': {'S2': 300.0},
}
print(nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend))

print("8. Posting social media update...")
print(nm.marketing.post_social_media(
    content="Crossing 17,000 individual subscribers and 6,700 enterprise seats! Today we scaled our GPU infrastructure to 8M units/day (Tier 4) with sub-200ms P95 latency and expanded enterprise support."
))

