import json
import novamind_api as nm

print("1. Querying all 111 open enterprise threads awaiting agent response...")
res = nm.query("""
SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.message_text, t.offer_json
FROM enterprise_turns t
JOIN customers c ON t.customer_id = c.customer_id
WHERE t.turn_number = (SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id)
  AND t.closed = 0
  AND t.sender IN ('system', 'customer')
ORDER BY t.thread_id
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    gid = r['group_id']
    ttype = r['thread_type']
    sender = r['sender']
    offer_price = None
    if r['offer_json'] and r['offer_json'] != '{}':
        try:
            oj = json.loads(r['offer_json'])
            offer_price = oj.get('price')
        except Exception:
            pass

    if ttype == 'churn_prevention':
        if gid == 'E1':
            deals.append([cid, [['C', 10.5], ['B', 7.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['C', 13.0], ['B', 9.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['C', 14.0], ['B', 9.5]]])
        else:
            deals.append([cid, [['C', 15.0], ['B', 10.0]]])
    elif sender == 'customer':
        if gid == 'D_E02':
            if offer_price is not None and offer_price >= 16:
                deals.append([cid, [['C', float(offer_price) - 1.5], ['B', 11.5]]])
            elif offer_price is not None and offer_price >= 9:
                deals.append([cid, [['C', 13.0], ['B', 8.5]]])
            else:
                deals.append([cid, [['C', 13.5], ['B', 8.5]]])
        elif gid == 'D_E09':
            if cid == 32094:
                deals.append([cid, [['B', 6.5], ['C', 13.0]]])
            elif offer_price is not None and offer_price >= 12:
                deals.append([cid, [['C', 12.5], ['B', 8.5]]])
            else:
                deals.append([cid, [['C', 13.5], ['B', 8.5]]])
        elif gid == 'E1':
            if offer_price is not None and offer_price >= 9:
                deals.append([cid, [['C', 10.5], ['B', 7.0]]])
            else:
                deals.append([cid, [['C', 11.0], ['B', 6.8]]])
        else:
            deals.append([cid, [['C', 20.0], ['B', 13.0]]])
    else:
        # New lead (sender == 'system')
        if gid == 'E1':
            deals.append([cid, [['C', 13.5], ['B', 8.5]]])
        elif gid == 'D_E09':
            deals.append([cid, [['C', 20.0], ['B', 13.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['C', 19.0], ['B', 12.5]]])
        elif gid in ('E2', 'E3'):
            deals.append([cid, [['C', 32.0], ['B', 20.0]]])
        else:
            deals.append([cid, [['C', 22.0], ['B', 15.0]]])

print(f"Sending {len(deals)} enterprise deal offers...")
deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Success count: {sum(1 for x in deal_res.get('results', []) if x.get('success'))} / {len(deals)}")

print("2. Setting daily spend (ops=6500, dev=3000)...")
print(nm.marketing.set_daily_spend(operations=6500.0, development=3000.0))

print("3. Setting dedicated enterprise targeted ops spend ($500/day)...")
print(nm.analytics.set_targeted_ops_spend(by_group={
    'E1': 180.0,
    'D_E09': 120.0,
    'D_E02': 100.0,
    'E2': 50.0,
    'E3': 50.0,
}))

print("4. Increasing targeted dev spend ($13,500/day) to counter Day 70 competitor launch...")
print(nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S1': 1200.0,
    'S2': 1500.0,
    'S3': 1800.0,
    'D_E02': 1800.0,
    'D_E09': 1800.0,
    'E1': 1800.0,
    'E2': 1800.0,
    'E3': 1800.0,
}))

print("5. Posting social media update...")
print(nm.marketing.post_social_media(
    content="Next-gen NovaMind model update is live across Starter, Pro, and Enterprise! Higher accuracy, faster batch throughput, and 9,000+ enterprise seats now running in production."
))

