import json
import novamind_api as nm

print("1. Querying all 86 open enterprise threads awaiting agent response...")
res = nm.query("""
SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.message_text, t.offer_json
FROM enterprise_turns t
JOIN customers c ON t.customer_id = c.customer_id
WHERE t.turn_number = (SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id)
  AND t.closed = 0
  AND t.sender IN ('system', 'customer')
ORDER BY t.thread_id
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    gid = r['group_id']
    ttype = r['thread_type']
    sender = r['sender']
    offer_price = None
    if r['offer_json'] and r['offer_json'] != '{}':
        try:
            oj = json.loads(r['offer_json'])
            offer_price = oj.get('price')
        except Exception:
            pass

    if ttype == 'churn_prevention':
        if gid == 'E1':
            deals.append([cid, [['B', 6.8], ['C', 10.0], ['A', 5.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 9.0], ['C', 13.5], ['A', 6.5]]])
        else:
            deals.append([cid, [['B', 8.5], ['C', 12.5], ['A', 6.0]]])
    elif sender == 'customer':
        if gid == 'D_E02':
            if offer_price is not None and offer_price >= 15:
                deals.append([cid, [['C', float(offer_price) - 1.0], ['B', 10.5], ['A', 7.0]]])
            elif offer_price is not None and offer_price >= 10:
                deals.append([cid, [['B', 8.5], ['C', 12.5], ['A', 6.0]]])
            else:
                deals.append([cid, [['B', 8.0], ['C', 13.0], ['A', 5.5]]])
        elif gid == 'D_E09':
            if offer_price is not None and offer_price >= 12:
                deals.append([cid, [['C', 12.0], ['B', 8.5], ['A', 6.0]]])
            elif offer_price is not None and offer_price >= 7:
                deals.append([cid, [['B', 7.5], ['C', 12.5], ['A', 5.5]]])
            else:
                deals.append([cid, [['B', 7.5], ['C', 13.0], ['A', 5.5]]])
        elif gid == 'E1':
            if offer_price is not None and offer_price >= 9:
                deals.append([cid, [['B', 7.0], ['C', 9.5], ['A', 5.0]]])
            elif offer_price is not None and offer_price >= 6:
                deals.append([cid, [['B', 6.5], ['C', 10.5], ['A', 4.8]]])
            else:
                deals.append([cid, [['B', 6.5], ['C', 11.0], ['A', 4.8]]])
        else:
            deals.append([cid, [['B', 13.0], ['C', 20.0], ['A', 9.0]]])
    else:
        # New lead (sender == 'system')
        if gid == 'E1':
            deals.append([cid, [['B', 8.5], ['A', 6.0], ['C', 14.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 12.0], ['A', 8.0], ['C', 19.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['B', 11.5], ['A', 7.5], ['C', 18.0]]])
        elif gid in ('E2', 'E3'):
            deals.append([cid, [['B', 18.0], ['C', 28.0], ['A', 12.0]]])
        else:
            deals.append([cid, [['B', 12.0], ['C', 19.0], ['A', 8.0]]])

print(f"Sending {len(deals)} enterprise deal offers...")
deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Success count: {sum(1 for x in deal_res.get('results', []) if x.get('success'))} / {len(deals)}")

print("2. Updating prices to A=21, B=55, C=115...")
print(nm.pricing.set_prices(A=21.0, B=55.0, C=115.0))

print("3. Updating lead promotions...")
print(nm.marketing.set_lead_promotion(
    global_promotion=0.0,
    by_group={'S1': 3.0, 'S2': 5.0, 'S3': 6.0}
))

print("4. Setting daily spend (ops=5000, dev=400)...")
print(nm.marketing.set_daily_spend(operations=5000.0, development=400.0))

print("5. Setting dedicated enterprise targeted ops spend ($400/day)...")
print(nm.analytics.set_targeted_ops_spend(by_group={
    'E1': 150.0,
    'D_E09': 110.0,
    'D_E02': 80.0,
    'E2': 30.0,
    'E3': 30.0,
}))

print("6. Setting targeted dev spend ($1,200/day) to harvest cash in Week 12...")
print(nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S1': 150.0,
    'S2': 150.0,
    'S3': 150.0,
    'D_E02': 150.0,
    'D_E09': 150.0,
    'E1': 150.0,
    'E2': 150.0,
    'E3': 150.0,
}))

print("7. Setting targeted ad spend ($3,500/day)...")
ad_spend = {
    'content_marketing': {'S1': 1400.0},
    'referral_program': {'S1': 800.0, 'S3': 600.0},
    'social_media': {'S2': 300.0, 'S3': 200.0},
    'linkedin': {'S2': 200.0},
}
print(nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend))

print("8. Testing in-app ads strength on 1 single customer (customer_id=7)...")
print(nm.marketing.set_ads_strength(global_strength=0.0, by_customer={'7': 0.05}))

print("9. Posting social media update...")
print(nm.marketing.post_social_media(
    content="23,600+ builders and 11,300+ enterprise seats now run on NovaMind! Check out our expanded API burst-limit documentation and flexible Starter/Pro enterprise plans."
))

