import json
import novamind_api as nm

print("1. Clearing 1-customer in-app ads test...")
print(nm.marketing.set_ads_strength(global_strength=0.0, by_customer={}))

print("2. Querying all 128 open enterprise threads awaiting agent response...")
res = nm.query("""
SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.message_text, t.offer_json
FROM enterprise_turns t
JOIN customers c ON t.customer_id = c.customer_id
WHERE t.turn_number = (SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id)
  AND t.closed = 0
  AND t.sender IN ('system', 'customer')
ORDER BY t.thread_id
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    gid = r['group_id']
    ttype = r['thread_type']
    sender = r['sender']
    offer_price = None
    if r['offer_json'] and r['offer_json'] != '{}':
        try:
            oj = json.loads(r['offer_json'])
            offer_price = oj.get('price')
        except Exception:
            pass

    if ttype == 'churn_prevention':
        if gid == 'E1':
            deals.append([cid, [['B', 7.5], ['A', 5.5], ['C', 11.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 9.5], ['A', 6.5], ['C', 14.0]]])
        else:
            deals.append([cid, [['B', 9.0], ['A', 6.0], ['C', 13.0]]])
    elif sender == 'customer':
        if gid == 'D_E02':
            if offer_price is not None and offer_price >= 9:
                deals.append([cid, [['B', 9.0], ['A', 6.0], ['C', 16.0]]])
            else:
                deals.append([cid, [['B', 8.0], ['A', 5.5], ['C', 16.0]]])
        elif gid == 'D_E09':
            if offer_price is not None and offer_price >= 9:
                deals.append([cid, [['B', 9.5], ['A', 6.5], ['C', 16.5]]])
            else:
                deals.append([cid, [['B', 8.0], ['A', 5.5], ['C', 16.5]]])
        elif gid == 'E1':
            if offer_price is not None and offer_price >= 8:
                deals.append([cid, [['B', 8.0], ['A', 5.5], ['C', 15.0]]])
            else:
                deals.append([cid, [['B', 7.0], ['A', 5.0], ['C', 15.0]]])
        elif gid in ('E2', 'E3'):
            deals.append([cid, [['B', 10.5], ['A', 7.0], ['C', 18.0]]])
        else:
            deals.append([cid, [['B', 10.0], ['A', 7.0], ['C', 18.0]]])
    else:
        # New lead (sender == 'system')
        if gid == 'E1':
            deals.append([cid, [['B', 9.5], ['A', 6.5], ['C', 17.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 13.5], ['A', 8.5], ['C', 22.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['B', 12.5], ['A', 8.0], ['C', 21.0]]])
        elif gid in ('E2', 'E3'):
            deals.append([cid, [['B', 18.0], ['C', 30.0], ['A', 11.0]]])
        else:
            deals.append([cid, [['B', 13.0], ['C', 22.0], ['A', 8.5]]])

print(f"Sending {len(deals)} enterprise deal offers...")
deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Success count: {sum(1 for x in deal_res.get('results', []) if x.get('success'))} / {len(deals)}")

print("3. Updating prices to A=21, B=56, C=125 and quotas to A=300, B=550, C=500...")
print(nm.pricing.set_prices(A=21.0, B=56.0, C=125.0))
print(nm.pricing.set_usage_quotas(A=300, B=550, C=500))

print("4. Setting daily spend (ops=7500, dev=2000)...")
print(nm.marketing.set_daily_spend(operations=7500.0, development=2000.0))

print("5. Setting dedicated enterprise targeted ops spend ($600/day)...")
print(nm.analytics.set_targeted_ops_spend(by_group={
    'E1': 200.0,
    'D_E09': 150.0,
    'D_E02': 120.0,
    'E2': 60.0,
    'E3': 70.0,
}))

print("6. Setting targeted dev spend ($8,000/day)...")
print(nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S1': 1000.0,
    'S2': 1000.0,
    'S3': 1000.0,
    'D_E02': 1000.0,
    'D_E09': 1000.0,
    'E1': 1000.0,
    'E2': 1000.0,
    'E3': 1000.0,
}))

print("7. Setting targeted ad spend ($4,000/day)...")
ad_spend = {
    'content_marketing': {'S1': 1600.0},
    'referral_program': {'S1': 900.0, 'S3': 700.0},
    'social_media': {'S2': 350.0, 'S3': 250.0},
    'linkedin': {'S2': 200.0},
}
print(nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend))

print("8. Posting social media update...")
print(nm.marketing.post_social_media(
    content="Approaching $1M in monthly recurring revenue with 25,800+ individual subscribers and 15,500+ enterprise seats! Expanded 24/7 technical support and high-efficiency Pro tiers."
))

