import json
import novamind_api as nm

print("1. Setting model tiers to A=1, B=2, C=2 to cut Plan C compute cost by 67%...")
print(nm.pricing.set_model_tiers(A=1, B=2, C=2))

print("2. Updating prices to A=21, B=54, C=82 and quotas to A=300, B=550, C=600...")
print(nm.pricing.set_prices(A=21.0, B=54.0, C=82.0))
print(nm.pricing.set_usage_quotas(A=300, B=550, C=600))

print("3. Querying all 160 open enterprise threads awaiting agent response...")
res = nm.query("""
SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type, t.turn_number, t.sender, t.day, t.seat_count, t.message_text, t.offer_json
FROM enterprise_turns t
JOIN customers c ON t.customer_id = c.customer_id
WHERE t.turn_number = (SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id)
  AND t.closed = 0
  AND t.sender IN ('system', 'customer')
ORDER BY t.thread_id
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    gid = r['group_id']
    ttype = r['thread_type']
    sender = r['sender']
    offer_price = None
    if r['offer_json'] and r['offer_json'] != '{}':
        try:
            oj = json.loads(r['offer_json'])
            offer_price = oj.get('price')
        except Exception:
            pass

    # Now both Plan B and Plan C use Model Tier 2 ($0.002/unit -> ~$3.00-$4.80/seat/mo compute cost!),
    # and Plan A uses Model Tier 1 ($0.0003/unit -> ~$0.50/seat/mo compute cost!).
    if ttype == 'churn_prevention':
        if gid == 'E1':
            deals.append([cid, [['B', 7.0], ['A', 5.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['B', 8.5], ['A', 6.0]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 9.0], ['A', 6.5]]])
        else:
            deals.append([cid, [['B', 9.0], ['A', 6.0]]])
    elif sender == 'customer':
        if gid == 'E3':
            if offer_price is not None and offer_price >= 14:
                deals.append([cid, [['B', 14.0], ['A', 9.0]]])
            else:
                deals.append([cid, [['B', 10.0], ['A', 6.5]]])
        elif gid == 'D_E09':
            if offer_price is not None and offer_price >= 12:
                deals.append([cid, [['B', float(offer_price) - 1.0], ['A', 7.5]]])
            else:
                deals.append([cid, [['B', 8.5], ['A', 6.0]]])
        elif gid == 'D_E02':
            if offer_price is not None and offer_price >= 10:
                deals.append([cid, [['B', float(offer_price) - 1.0], ['A', 6.5]]])
            else:
                deals.append([cid, [['B', 8.0], ['A', 5.5]]])
        elif gid == 'E1':
            if offer_price is not None and offer_price >= 8:
                deals.append([cid, [['B', float(offer_price) - 0.5], ['A', 5.5]]])
            else:
                deals.append([cid, [['B', 6.8], ['A', 4.8]]])
        else:
            deals.append([cid, [['B', 10.0], ['A', 7.0]]])
    else:
        # New lead (sender == 'system')
        if gid == 'E1':
            deals.append([cid, [['B', 9.5], ['A', 6.5]]])
        elif gid == 'D_E09':
            deals.append([cid, [['B', 14.0], ['A', 9.0]]])
        elif gid == 'D_E02':
            deals.append([cid, [['B', 13.0], ['A', 8.5]]])
        elif gid in ('E2', 'E3'):
            deals.append([cid, [['B', 18.0], ['A', 11.5]]])
        else:
            deals.append([cid, [['B', 12.0], ['A', 8.0]]])

print(f"Sending {len(deals)} enterprise deal offers...")
deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Success count: {sum(1 for x in deal_res.get('results', []) if x.get('success'))} / {len(deals)}")

print("4. Setting daily spend (ops=9000, dev=3200)...")
print(nm.marketing.set_daily_spend(operations=9000.0, development=3200.0))

print("5. Setting dedicated enterprise targeted ops spend ($800/day)...")
print(nm.analytics.set_targeted_ops_spend(by_group={
    'E1': 280.0,
    'D_E09': 200.0,
    'D_E02': 160.0,
    'E2': 80.0,
    'E3': 80.0,
}))

print("6. Setting targeted dev spend ($12,800/day)...")
print(nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S1': 1600.0,
    'S2': 1600.0,
    'S3': 1600.0,
    'D_E02': 1600.0,
    'D_E09': 1600.0,
    'E1': 1600.0,
    'E2': 1600.0,
    'E3': 1600.0,
}))

print("7. Setting targeted ad spend ($4,500/day)...")
ad_spend = {
    'content_marketing': {'S1': 1800.0},
    'referral_program': {'S1': 1000.0, 'S3': 800.0},
    'social_media': {'S2': 400.0, 'S3': 300.0},
    'linkedin': {'S2': 200.0},
}
print(nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend))

print("8. Posting social media update...")
print(nm.marketing.post_social_media(
    content="Surpassing $1.13M in monthly recurring revenue with 28,200+ individual subscribers and 21,600+ enterprise seats! Lowered Plan C price to $82/mo with 600K/day quota."
))

